import { escapeSelector } from "jquery";
import { motion, MotionConfig, time } from "framer-motion";
const Footer = () => {
  const date = new Date();
    const showTime = date.getHours() 
        + ':' + date.getMinutes() 
        + ":" + date.getSeconds()
  return (
    <section className="footer">
    <footer class="bg-dark">
  <div class="container p-4 pb-0">

    <section class="mb-4">
     
      <a
      data-mdb-ripple-init
        class="btn text-white btn-floating m-1"
        style={{color: + 'red'}}
        href="#!"
        role="button"
        ><i class="fab fa-facebook-f"></i
      ></a>

    
      <a
        data-mdb-ripple-init
        class="btn text-white btn-floating m-1"
        style={{color: + 'blue'}}
        href="#!"
        role="button"
        ><i class="fab fa-twitter"></i
      ></a>


      <a
        data-mdb-ripple-init
        class="btn text-white btn-floating m-1"
        style={{color: + 'green'}}
        href="#!"
        role="button"
        ><i class="fab fa-google"></i
      ></a>


      <a
        data-mdb-ripple-init
        class="btn text-white btn-floating m-1"
        style={{color: + 'yellow'}}
        href="#!"
        role="button"
        ><i class="fab fa-instagram"></i
      ></a>

      <a
        data-mdb-ripple-init
        class="btn text-white btn-floating m-1"
        style={{color: + 'blue'}}
        href="#!"
        role="button"
        ><i class="fab fa-linkedin-in"></i
      ></a>
   
      <a
        data-mdb-ripple-init
        class="btn text-white btn-floating m-1"
        style={{color: + 'yellow'}}
        href="#!"
        role="button"
        ><i class="fab fa-github"></i
      ></a>
    </section>
 
  </div>
  <div class="bg-primary" style={{color: + 'red'}}>
  <motion.h1 animate={{color:'red', transition:-200}}>{showTime}</motion.h1>
    <a class="text-body" href="#">Gilbert George</a>
  </div>
  <motion.div animate={{ color:'pink' }}> <motion.h1 animate={{scale:1}} >You Rock</motion.h1></motion.div>

</footer>
      
    
    </section>
  );
};

export default Footer